// Шапка заявления работодателю: адресат справа, заявитель ниже (исп. делопроизводство)
const workHdr = (): TplDef['body'] => [
  { type: 'lines', align: 'right', items: ['{{org_name}}', 'A la atención de: {{head_name}}', '', '{{applicant_name}}', 'DNI/NIE: {{applicant_dni}}', '{{date_today}}'] },
];

const workFields = (extra: TplDef['fields'] = []): TplDef['fields'] => [
  F('org_name', 'Название компании', 'Company name', 'text', { half: true, placeholderDoc: 'Comercial Ejemplo, S.L.' }),
  F('head_name', 'Кому (RRHH/руководитель)', 'Submit to', 'text', { half: true, placeholderDoc: 'Departamento de Recursos Humanos' }),
  F('applicant_name', 'Ваше имя', 'Your full name', 'text', { half: true, placeholderDoc: 'Juan García López' }),
  F('applicant_dni', 'Ваш DNI/NIE', 'Your DNI/NIE', 'text', { half: true, placeholderDoc: 'DNI 12345678Z' }),
  ...extra,
];

const personFields = (extra: TplDef['fields'] = []): TplDef['fields'] => [
  F('applicant_name', 'Ваше имя', 'Your full name', 'text', { half: true, placeholderDoc: 'Juan García López' }),
  F('applicant_dni', 'Ваш DNI/NIE', 'Your DNI/NIE', 'text', { half: true, placeholderDoc: 'DNI 12345678Z' }),
  F('applicant_address', 'Ваш адрес', 'Your address', 'text', { half: true, placeholderDoc: 'Calle de Alcalá 45, 28014 Madrid' }),
  F('applicant_phone', 'Телефон', 'Phone', 'text', { half: true, placeholderDoc: '600 123 456' }),
  ...extra,
];

